from flask import Flask, redirect, url_for, request

app = Flask(__name__)

# サンプルの有効な URL
VALID_URLS = {
    "http://example.com",
    "https://example.com",
    "http://google.com",
    "https://google.com"
}

def redirect_invalid_url(url):
    # URL が None または空の場合は無効
    if not url:
        return False
    # URL が http:// または https:// で始まっていない場合
    if not url.startswith('http://') and not url.startswith('https://'):
        return False
    # URL が有効なリストに存在するかチェック
    if url in VALID_URLS:
        return True
    return False

@app.route('/redirect/<url>')
def redirect_to_url(url):
    if redirect_invalid_url(url):
        return redirect(url)
    else:
        return "エラー: 有効な URL ではありません。", 400

if __name__ == '__main__':
    app.run(debug=True)

