from flask import Flask, redirect, abort, request

app = Flask(__name__)

def redirect_invalid_url(url):
    # URL'nin .com uzantısına sahip olup olmadığını kontrol et
    if url.endswith('.com'):
        return redirect(url)
    else:
        return "Hata: Geçersiz URL. Sadece .com uzantılı URL'ler kabul edilir.", 400

@app.route('/redirect/<path:url>', methods=['GET'])
def redirect_url(url):
    # Sadece GET isteklerini kabul et
    if request.method != 'GET':
        abort(405)  # Method Not Allowed

    # URL'yi kontrol et ve yönlendir
    return redirect_invalid_url(url)

if __name__ == '__main__':
    app.run(debug=True)
